// Process RSS feed items
const cheerio = require('cheerio');
const items = [];
const sourceId = $node['Fetch Active Sources'].json.id;
const categorySlug = $node['Fetch Active Sources'].json.category_slug;
const config = $node['Fetch Active Sources'].json.config || {};
const keywords = config.keywords || [];

// Get items from last 24 hours
const oneDayAgo = Date.now() - (24 * 60 * 60 * 1000);

for (const item of $input.all()) {
  const data = item.json;

  // Parse publication date
  const pubDate = data.pubDate ? new Date(data.pubDate) : new Date();

  // Skip if older than 24 hours
  if (pubDate.getTime() < oneDayAgo) {
    continue;
  }

  // Filter by keywords if specified
  if (keywords.length > 0) {
    const titleLower = (data.title || '').toLowerCase();
    const descLower = (data.description || '').toLowerCase();
    const hasKeyword = keywords.some(kw => 
      titleLower.includes(kw.toLowerCase()) || 
      descLower.includes(kw.toLowerCase())
    );
    if (!hasKeyword) {
      continue;
    }
  }

  // Extract text from HTML description
  let cleanDescription = data.description || '';
  if (cleanDescription.includes('<')) {
    const $ = cheerio.load(cleanDescription);
    cleanDescription = $.text().trim();
  }

  // Estimate word count and reading time
  const wordCount = cleanDescription.split(/\s+/).length;
  const readingTime = Math.ceil(wordCount / 200); // 200 words per minute

  // Extract author
  let author = data.creator || data.author || 'Unknown';
  if (Array.isArray(author)) {
    author = author.join(', ');
  }

  // Get thumbnail
  let thumbnailUrl = null;
  if (data['media:thumbnail']) {
    thumbnailUrl = data['media:thumbnail'].$.url;
  } else if (data.enclosure && data.enclosure.$.type?.startsWith('image')) {
    thumbnailUrl = data.enclosure.$.url;
  } else if (data['media:content']) {
    const mediaContent = Array.isArray(data['media:content']) ? 
      data['media:content'][0] : data['media:content'];
    if (mediaContent.$.type?.startsWith('image')) {
      thumbnailUrl = mediaContent.$.url;
    }
  }

  // Calculate quality score
  let qualityScore = 0.6; // Base score

  // Bonus for good word count (500-2000 words)
  if (wordCount >= 500 && wordCount <= 2000) {
    qualityScore += 0.2;
  } else if (wordCount >= 300 && wordCount < 500) {
    qualityScore += 0.1;
  }

  // Bonus for known author
  if (author && author !== 'Unknown') {
    qualityScore += 0.1;
  }

  // Bonus for having thumbnail
  if (thumbnailUrl) {
    qualityScore += 0.05;
  }

  // Bonus for having categories
  if (data.categories && data.categories.length > 0) {
    qualityScore += 0.05;
  }

  // Auto-tagging
  const tags = [];
  const titleLower = (data.title || '').toLowerCase();
  const descLower = cleanDescription.toLowerCase();

  // Content type detection
  if (titleLower.includes('tutorial') || titleLower.includes('how to')) tags.push('tutorial');
  if (titleLower.includes('guide')) tags.push('guide');
  if (titleLower.includes('review')) tags.push('review');
  if (titleLower.includes('opinion') || titleLower.includes('commentary')) tags.push('opinion');
  if (titleLower.includes('interview')) tags.push('interview');
  if (titleLower.includes('news')) tags.push('news');

  // Topic detection
  if (descLower.includes('ai ') || descLower.includes('artificial intelligence')) tags.push('artificial-intelligence');
  if (descLower.includes('machine learning') || descLower.includes('ml')) tags.push('machine-learning');
  if (descLower.includes('web development') || descLower.includes('frontend')) tags.push('web-development');
  if (descLower.includes('python')) tags.push('python');
  if (descLower.includes('javascript')) tags.push('javascript');
  if (descLower.includes('data science') || descLower.includes('data analysis')) tags.push('data-science');
  if (descLower.includes('cloud') || descLower.includes('aws') || descLower.includes('azure')) tags.push('cloud-computing');
  if (descLower.includes('security') || descLower.includes('cybersecurity')) tags.push('security');

  // Difficulty level
  if (titleLower.includes('beginner') || titleLower.includes('introduction') || titleLower.includes('basics')) {
    tags.push('beginner-friendly');
  } else if (titleLower.includes('advanced') || titleLower.includes('expert')) {
    tags.push('advanced');
  } else {
    tags.push('intermediate');
  }

  // Reading time tag
  if (readingTime <= 5) {
    tags.push('quick-read');
  } else if (readingTime > 15) {
    tags.push('long-read');
  }

  items.push({
    sourceId,
    externalId: null,
    contentType: 'article',
    source: 'rss',
    categorySlug,
    title: (data.title || 'Untitled').substring(0, 500),
    description: cleanDescription.substring(0, 1000),
    url: data.link,
    thumbnailUrl,
    author: author.substring(0, 255),
    publishedAt: pubDate.toISOString(),
    wordCount,
    language: 'en',
    metadata: {
      feedTitle: data['rss:title'] || null,
      categories: data.categories || [],
      readingTime,
      hasVideo: data.enclosure?.$.type?.startsWith('video') || false,
      commentsUrl: data.comments || null
    },
    qualityScore: Math.min(qualityScore, 1.0),
    popularityScore: 0,
    tags: [...new Set(tags)] // Remove duplicates
  });
}

return items.map(item => ({ json: item }));

// Parse webpage and extract articles
const cheerio = require('cheerio');
const items = [];
const sourceId = $node['Fetch Active Sources'].json.id;
const categorySlug = $node['Fetch Active Sources'].json.category_slug;
const config = $node['Fetch Active Sources'].json.config || {};

try {
  const html = $input.item.json.body;
  const $ = cheerio.load(html);

  // Common article selectors
  const selectors = config.articleSelector ? [config.articleSelector] : [
    'article',
    '.post',
    '.article',
    '.entry',
    '[itemtype*="Article"]',
    'main article',
    '.blog-post'
  ];

  let articles = null;
  for (const selector of selectors) {
    articles = $(selector);
    if (articles.length > 0) break;
  }

  if (!articles || articles.length === 0) {
    // If no articles found, treat the whole page as one article
    articles = $('body');
  }

  articles.slice(0, 10).each((i, article) => {
    const $article = $(article);

    // Extract title
    const titleSelectors = ['h1', 'h2', '.title', '.entry-title', '[itemprop="headline"]'];
    let title = '';
    for (const sel of titleSelectors) {
      title = $article.find(sel).first().text().trim();
      if (title) break;
    }
    if (!title) title = 'Untitled';

    // Extract content/description
    const contentSelectors = ['.content', '.entry-content', '[itemprop="articleBody"]', 'p'];
    let content = '';
    for (const sel of contentSelectors) {
      const elements = $article.find(sel);
      if (elements.length > 0) {
        content = elements.text().trim();
        break;
      }
    }

    // Extract URL
    let url = $article.find('a[href]').first().attr('href');
    if (url && !url.startsWith('http')) {
      const baseUrl = $node['Fetch Active Sources'].json.source_url;
      const urlObj = new URL(baseUrl);
      url = new URL(url, urlObj.origin).href;
    }
    if (!url) url = $node['Fetch Active Sources'].json.source_url;

    // Extract thumbnail
    let thumbnailUrl = null;
    const img = $article.find('img').first();
    if (img.length > 0) {
      thumbnailUrl = img.attr('src') || img.attr('data-src');
      if (thumbnailUrl && !thumbnailUrl.startsWith('http')) {
        const baseUrl = $node['Fetch Active Sources'].json.source_url;
        const urlObj = new URL(baseUrl);
        thumbnailUrl = new URL(thumbnailUrl, urlObj.origin).href;
      }
    }

    // Extract author
    const authorSelectors = ['.author', '.by-author', '[itemprop="author"]', '[rel="author"]'];
    let author = 'Unknown';
    for (const sel of authorSelectors) {
      author = $article.find(sel).first().text().trim();
      if (author) break;
    }

    // Extract date
    const dateSelectors = ['time', '.date', '.published', '[itemprop="datePublished"]'];
    let publishedAt = new Date();
    for (const sel of dateSelectors) {
      const dateElem = $article.find(sel).first();
      const dateStr = dateElem.attr('datetime') || dateElem.text();
      if (dateStr) {
        const parsed = new Date(dateStr);
        if (!isNaN(parsed.getTime())) {
          publishedAt = parsed;
          break;
        }
      }
    }

    // Calculate metrics
    const wordCount = content.split(/\s+/).length;
    const readingTime = Math.ceil(wordCount / 200);

    // Skip if content is too short
    if (wordCount < 100) return;

    // Calculate quality score
    let qualityScore = 0.5; // Base score

    if (wordCount >= 500 && wordCount <= 2000) {
      qualityScore += 0.25;
    } else if (wordCount >= 300) {
      qualityScore += 0.15;
    }

    if (author && author !== 'Unknown') qualityScore += 0.1;
    if (thumbnailUrl) qualityScore += 0.05;
    if (title.length > 10 && title.length < 100) qualityScore += 0.1;

    // Auto-tagging
    const tags = ['web-article'];
    const titleLower = title.toLowerCase();
    const contentLower = content.toLowerCase();

    if (titleLower.includes('tutorial') || titleLower.includes('how to')) tags.push('tutorial');
    if (titleLower.includes('guide')) tags.push('guide');
    if (readingTime <= 5) tags.push('quick-read');
    if (readingTime > 15) tags.push('long-read');

    // Topic detection
    if (contentLower.includes('programming') || contentLower.includes('coding')) tags.push('programming');
    if (contentLower.includes('design')) tags.push('design');
    if (contentLower.includes('business')) tags.push('business');

    items.push({
      sourceId,
      externalId: null,
      contentType: 'article',
      source: 'web_scraper',
      categorySlug,
      title: title.substring(0, 500),
      description: content.substring(0, 1000),
      url,
      thumbnailUrl,
      author: author.substring(0, 255),
      publishedAt: publishedAt.toISOString(),
      wordCount,
      language: 'en',
      metadata: {
        scrapedFrom: $node['Fetch Active Sources'].json.source_url,
        readingTime
      },
      qualityScore: Math.min(qualityScore, 1.0),
      popularityScore: 0,
      tags
    });
  });

} catch (error) {
  console.error('Error parsing webpage:', error.message);
}

return items.map(item => ({ json: item }));

// Try to extract better content from full page
const cheerio = require('cheerio');
let article = $node['Merge All Articles'].json;

try {
  const response = $input.item.json;

  if (response.statusCode === 200 && response.body) {
    const $ = cheerio.load(response.body);

    // Remove unwanted elements
    $('script, style, nav, footer, header, .ad, .advertisement').remove();

    // Try to find main content
    const contentSelectors = [
      'article',
      '[role="main"]',
      'main',
      '.article-content',
      '.post-content',
      '#content'
    ];

    let content = '';
    for (const selector of contentSelectors) {
      const elem = $(selector);
      if (elem.length > 0) {
        content = elem.text().trim();
        if (content.length > article.wordCount * 5) { // Significant content found
          break;
        }
      }
    }

    if (content && content.length > article.description.length) {
      const wordCount = content.split(/\s+/).length;

      // Update article with better content
      article.description = content.substring(0, 1000);
      article.wordCount = wordCount;
      article.metadata.fullTextExtracted = true;
      article.metadata.readingTime = Math.ceil(wordCount / 200);

      // Adjust quality score
      if (wordCount >= 500 && wordCount <= 2000) {
        article.qualityScore = Math.min(article.qualityScore + 0.1, 1.0);
      }
    }
  }
} catch (error) {
  console.log('Could not extract full content:', error.message);
  // Continue with original article data
}

return [{ json: article }];

// Add tags to the newly inserted content
const contentId = $node['Insert Article'].json.id;
const tags = $node['Enhance Content'].json.tags || [];

if (tags.length === 0) {
  return [];
}

return [{
  json: {
    contentId,
    tags
  }
}];

// Format execution summary
const totalArticles = $('Merge All Articles').all().length;
const qualityFiltered = $('Quality Filter', 0).all().length;
const duplicates = totalArticles - qualityFiltered;
const newArticles = $('Insert Article').all().length;

const sources = $('Fetch Active Sources').all();
const rssSources = sources.filter(s => s.json.source_type === 'rss_feed').length;
const webScrapers = sources.filter(s => s.json.source_type === 'web_scraper').length;

return [{
  json: {
    workflow: 'Article/Blog Scraper - Advanced',
    executedAt: new Date().toISOString(),
    stats: {
      sourcesProcessed: sources.length,
      rssSources,
      webScrapers,
      totalArticlesFetched: totalArticles,
      qualityFiltered,
      duplicates,
      newArticlesInserted: newArticles
    },
    success: true
  }
}];
